import{z as l,x as o,o as B,c as s,q as A,j as t,D as a,d as i,s as r,S as n}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"负债驱动投资 LDI","description":"","frontmatter":{"title":"负债驱动投资 LDI","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/bm2-ldi.md","filePath":"quant/bm2-ldi.md","lastUpdated":1791413859000}'),d={name:"quant/bm2-ldi.md"};function D(p,E,_,m,F,C){const e=o("Mermaid");return B(),s("div",null,[E[2]||(E[2]=A('<h1 id="负债驱动投资-ldi" tabindex="-1">负债驱动投资 LDI <a class="header-anchor" href="#负债驱动投资-ldi" aria-label="Permalink to &quot;负债驱动投资 LDI&quot;">​</a></h1><div class="epigraph"><p>养老金的成绩不是同类排名的百分位，而是资金比率的变动——LDI 把这句话从口号变成资产负债表结构。</p><footer>—— 据 Fabozzi, Bond Markets, Analysis and Strategies 相关章节整理</footer></div><p><a href="/quant/bm2-duration-immunization">上一课</a>把单笔负债对平移曲线免疫，且只有一阶保证。真实的养老负债是一串跨几十年的支付，一半还挂通胀；久期免疫由此升级为 LDI：以负债为基准管理资产，把组合切成负债匹配与收益追逐两个模块。本课写这场升级的三个问题：负债怎么成为基准、对冲用什么工具、杠杆与抵押把哪些新风险接了进来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>上一课的免疫目标是单个到期日的标量；LDI 的基准是一个负债函数：支付日谱、通胀挂钩比例、折现口径（经济或监管）。业绩不再对指数衡量，而看资金比率 \\(F = V_A / V_L\\) 的变动——资产与负债必须放在同一张账上对冲。缺口有二：其一是期限，负债久期常在 12 年以上，长端现券既贵又稀薄，纯现券匹配吃不消；其二是资本，把全部资产锁进长债，收益追逐仓位就没有预算了，可养老金的缴费与待遇调整恰恰需要那部分收益。LDI 的设计目标因此是：用尽量少的资本把负债敏感度对冲掉，把省下的资本留给收益组合。</p><p><span class="marginnote">数字实例：资金比率 \\(F = V_A / V_L\\) 就是「资产市值除以负债折现值」。比如资产 100 亿、负债折现 95 亿，\\(F \\approx 1.05\\)。养老金的成绩不看今年跑赢同行几个百分点，而看这个比值——从 1.05 掉到 0.98，意味着按今天的市价算，钱已经不够付未来的待遇了。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>第一刀是切分：负债匹配组合（LMP）与收益追逐组合（RSP）。LMP 的工具阶梯从实到虚：现金流匹配（每个支付日找券，最稳但资本最重、长端常买不齐）、久期向量匹配（按 <a href="/quant/key-tenor-dv01">关键期限 DV01</a> 分桶对齐）、衍生品覆盖（收固定利率的利率互换补长端久期，国债期货补中段，通胀互换挂通胀腿）。对冲比率是决策变量而不是常数：按资金比率目标与风险预算定，通常留一部分敞口给缴费来源。RSP 在剩余风险预算内配股权与另类，其约束只有一条——它的尾部不得击穿资金比率的下限。</p>',8)),(B(),t(n,null,{default:a(()=>[r(e,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20LB%5B%22%E8%B4%9F%E5%80%BA%E6%A1%A3%E6%A1%88%EF%BC%9A%E6%94%AF%E4%BB%98%E8%B0%B1%E3%80%81%E9%80%9A%E8%83%80%E6%8C%82%E9%92%A9%E3%80%81%E6%8A%98%E7%8E%B0%E5%8F%A3%E5%BE%84%22%5D%20--%3E%20SP%5B%22%E5%88%87%E5%88%86%EF%BC%9A%E8%B4%9F%E5%80%BA%E5%8C%B9%E9%85%8D%E7%BB%84%E5%90%88%E5%8A%A0%E6%94%B6%E7%9B%8A%E7%BB%84%E5%90%88%22%5D%0A%20%20SP%20--%3E%20LMP%5B%22LMP%EF%BC%9A%E7%8E%B0%E5%88%B8%E3%80%81%E6%94%B6%E5%9B%BA%E4%BA%92%E6%8D%A2%E3%80%81%E5%9B%BD%E5%80%BA%E6%9C%9F%E8%B4%A7%22%5D%0A%20%20LMP%20--%3E%20HR%5B%22%E5%AF%B9%E5%86%B2%E6%AF%94%E7%8E%87%E6%8C%89%E5%85%B3%E9%94%AE%E6%9C%9F%E9%99%90%20DV01%20%E6%A0%A1%E5%87%86%22%5D%0A%20%20SP%20--%3E%20RSP%5B%22RSP%EF%BC%9A%E9%A3%8E%E9%99%A9%E9%A2%84%E7%AE%97%E5%86%85%E7%9A%84%E6%94%B6%E7%9B%8A%E8%B5%84%E4%BA%A7%22%5D%0A%20%20HR%20--%3E%20ST%5B%22%E5%8E%8B%E5%8A%9B%EF%BC%9A%E5%B9%B3%E8%A1%8C%E3%80%81%E9%99%A1%E5%B9%B3%E3%80%81%E9%80%9A%E8%83%80%E3%80%81%E8%BF%BD%E4%BF%9D%E8%B7%AF%E5%BE%84%22%5D%0A%20%20ST%20--%3E%20GV%7B%22%E6%8A%B5%E6%8A%BC%E8%B7%AF%E5%BE%84%E6%98%AF%E5%90%A6%E5%8F%AF%E6%89%BF%E5%8F%97%22%7D%0A%20%20GV%20--%3E%20FIX%5B%22%E9%A2%84%E7%AD%B9%E6%8A%B5%E6%8A%BC%E6%88%96%E9%99%8D%E6%9D%A0%E6%9D%86%22%5D%0A%20%20GV%20--%3E%20OK%5B%22%E7%BB%B4%E6%8C%81%E5%AF%B9%E5%86%B2%22%5D%0A%20%20FIX%20--%3E%20LMP%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[i(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>衍生品为什么在 LDI 里是必需品而非点缀：互换与期货不占本金，同样的 DV01 只占用零星保证金，省下的现金进入 RSP——这是资本效率的正收益。但「不占本金」是记账口径，抵押是真实的：CSA 追保与期货逐日盯市把利率风险转成流动性风险，杠杆则把转换放大。2022 年 9 月的英国把机制演示成案例：长端收益率上行触发 LDI 基金追保，被迫抛售 gilt，收益率再上行——<a href="/quant/rc-collateral-funding">抵押品与资金链</a>的折价—杠杆螺旋在国债市场重演，直到英格兰银行入场。<a href="/quant/bm2-duration-immunization">上一课</a>立的判据在此升级为治理条款：对冲方案必须连同抵押路径一起过压力，只压曲线不压追保的压力测试测不到真正的死因。</p><p><span class="marginnote">据英格兰银行金融政策委员会事后记录，事件前 LDI 基金杠杆普遍在数倍量级；9 月 28 日宣布的长端国债购买计划规模上限约 650 亿英镑。杠杆倍数各家统计口径不一，引用时须带出处与日期。</span></p><p><span class="marginnote">术语翻译：CSA（信用支持附件）是互换双方签的「抵押规则书」，约定盯市亏损超过阈值时，亏损方必须在几天内补交现金或国债。它把纸面浮亏变成「明天就得拿出来的现金」——利率风险正是在这一步被翻译成流动性风险的。</span></p>',4)),(B(),t(n,null,{default:a(()=>[r(e,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20R1%5B%22%E9%95%BF%E7%AB%AF%E6%94%B6%E7%9B%8A%E7%8E%87%E4%B8%8A%E8%A1%8C%22%5D%20--%3E%20M1%5B%22%E4%BA%92%E6%8D%A2%E4%B8%8E%E6%9C%9F%E8%B4%A7%E7%9B%AF%E5%B8%82%E4%BA%8F%E6%8D%9F%22%5D%0A%20%20M1%20--%3E%20C1%5B%22CSA%20%E8%BF%BD%E4%BF%9D%EF%BC%9A%E9%99%90%E6%9C%9F%E8%A1%A5%E6%8A%B5%E6%8A%BC%E5%93%81%22%5D%0A%20%20C1%20--%3E%20S1%5B%22%E6%8A%9B%E5%94%AE%20gilt%20%E8%9E%8D%E8%B5%84%22%5D%0A%20%20S1%20--%3E%20P1%5B%22%E4%BB%B7%E6%A0%BC%E4%B8%8B%E8%B7%8C%EF%BC%8C%E6%94%B6%E7%9B%8A%E7%8E%87%E5%86%8D%E4%B8%8A%E8%A1%8C%22%5D%0A%20%20P1%20--%3E%20R1%0A%20%20R1%20--%3E%20BOE%5B%22%E5%A4%AE%E8%A1%8C%E5%85%A5%E5%9C%BA%E8%B4%AD%E5%80%BA%EF%BC%8C%E8%9E%BA%E6%97%8B%E4%B8%AD%E6%96%AD%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[i(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>现金流匹配对任何曲线形状都免疫，但资本占用与长端流动性常常不允许；互换覆盖长端却留下互换—国债基差，利差走阔时「已对冲」的报表仍会动（<a href="/quant/swap-spread">互换利差</a>一课的口径）；通胀挂钩负债要用真实利率工具对冲，名义久期匹配会漏掉实际利率腿。折现口径是另一个暗坑：监管折现率滞后于市场时，资金比率与经济现实脱节，对冲比率定在哪条曲线上要事先声明。最后，LMP 与 RSP 的切分不是防火墙：RSP 的尾部损失同样压资金比率，抵押告急时最先被卖的往往是它——切分只是让责任清楚，不改变一张资产负债表的事实。</p><p><span class="marginnote">常见误区：初学者容易把 LMP 和 RSP 想成两个独立的钱包，实际它们是同一张资产负债表上的两个抽屉。RSP 的尾部亏损同样压低资金比率，抵押告急时最先被抛的往往就是 RSP——抽屉分得再清，出事时钱是连着的。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LDI 把基准从指数换成负债函数，业绩口径改为资金比率的变动。</li><li>LMP/RSP 切分：用最少资本对掉负债敏感度，把资本留给收益组合。</li><li>工具阶梯：现金流匹配、久期向量匹配、互换与期货覆盖，按资本效率与流动性选择。</li><li>衍生品把利率风险转成抵押与流动性风险，压力必须触发追保路径。</li><li>出处：据 Fabozzi 相关章节整理；2022 年英国事件口径见英格兰银行金融政策委员会记录与<a href="/quant/rc-case-map">利率信用案例</a>。</li></ul>',5))])}const h=l(d,[["render",D]]);export{P as __pageData,h as default};
